-- ============================================================================
-- Online Voting System (OVS) — Standalone Custom PostgreSQL Integrity Script
-- Phase 8.1.2: Complete Database Integrity, Constraints, Triggers & Reconciliation
-- ============================================================================
-- NOTE: This script documents and specifies the complete PostgreSQL 16+ DDL
-- and procedural logic required beyond standard Prisma Schema Language (PSL).
-- All table, column, and enum names EXACTLY match the snake_case mappings 
-- generated by PRISMA_SCHEMA_DRAFT.prisma.
-- DO NOT EXECUTE against development databases without dedicated migration tooling.
-- ============================================================================

-- ============================================================================
-- SECTION 1: COMPOSITE KEYS & REFERENTIAL INTEGRITY CONSTRAINTS
-- ============================================================================

-- 1.1 District & PC Composite Uniqueness (Enabled for composite FK references)
ALTER TABLE districts 
  ADD CONSTRAINT uq_districts_id_state 
  UNIQUE (id, state_id);

ALTER TABLE parliamentary_constituencies 
  ADD CONSTRAINT uq_parliamentary_constituencies_id_state 
  UNIQUE (id, state_id);

ALTER TABLE assembly_constituencies 
  ADD CONSTRAINT uq_assembly_constituencies_id_state 
  UNIQUE (id, state_id);

ALTER TABLE assembly_constituencies 
  ADD CONSTRAINT uq_assembly_constituencies_id_parent_pc 
  UNIQUE (id, parent_parliamentary_constituency_id);

ALTER TABLE candidates 
  ADD CONSTRAINT uq_candidates_id_party 
  UNIQUE (id, party_id);

-- 1.2 Multi-Level Geographic Composite Foreign Keys
-- Enforce that an AC strictly belongs to a District and PC within the same State
ALTER TABLE assembly_constituencies
  ADD CONSTRAINT fk_ac_district_state
  FOREIGN KEY (district_id, state_id) 
  REFERENCES districts(id, state_id) 
  ON DELETE RESTRICT;

ALTER TABLE assembly_constituencies
  ADD CONSTRAINT fk_ac_parent_pc_state
  FOREIGN KEY (parent_parliamentary_constituency_id, state_id) 
  REFERENCES parliamentary_constituencies(id, state_id) 
  ON DELETE RESTRICT;

-- Enforce that a Voter's AC strictly belongs to their assigned PC and District in the same State
ALTER TABLE voter_profiles
  ADD CONSTRAINT fk_voter_district_state
  FOREIGN KEY (district_id, state_id) 
  REFERENCES districts(id, state_id) 
  ON DELETE RESTRICT;

ALTER TABLE voter_profiles
  ADD CONSTRAINT fk_voter_pc_state
  FOREIGN KEY (parliamentary_constituency_id, state_id) 
  REFERENCES parliamentary_constituencies(id, state_id) 
  ON DELETE RESTRICT;

ALTER TABLE voter_profiles
  ADD CONSTRAINT fk_voter_ac_parent_pc
  FOREIGN KEY (assembly_constituency_id, parliamentary_constituency_id) 
  REFERENCES assembly_constituencies(id, parent_parliamentary_constituency_id) 
  ON DELETE RESTRICT;

-- Enforce Candidate-Party consistency in Tallies
ALTER TABLE candidate_tallies
  ADD CONSTRAINT fk_tally_candidate_party
  FOREIGN KEY (candidate_id, party_id) 
  REFERENCES candidates(id, party_id) 
  ON DELETE CASCADE;

-- ============================================================================
-- SECTION 2: PARTIAL UNIQUE INDEXES (NULLABLE COMPOSITE UNIQUENESS)
-- ============================================================================

-- 2.1 Election Constituencies (Exact single mapping per election)
CREATE UNIQUE INDEX IF NOT EXISTS uq_election_constituency_pc 
  ON election_constituencies (election_id, parliamentary_constituency_id) 
  WHERE parliamentary_constituency_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_election_constituency_ac 
  ON election_constituencies (election_id, assembly_constituency_id) 
  WHERE assembly_constituency_id IS NOT NULL;

-- 2.2 Candidate Nominations (Per-constituency uniqueness for candidate per election)
-- Note: A candidate may contest up to 2 constituencies per RPA 1951 s.33(7),
-- but cannot have duplicate nominations in the exact same constituency.
CREATE UNIQUE INDEX IF NOT EXISTS uq_nomination_candidate_election_pc 
  ON candidate_nominations (candidate_id, election_id, parliamentary_constituency_id) 
  WHERE parliamentary_constituency_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_nomination_candidate_election_ac 
  ON candidate_nominations (candidate_id, election_id, assembly_constituency_id) 
  WHERE assembly_constituency_id IS NOT NULL;

-- 2.3 Counting Sessions (Exact single counting session per constituency per election)
CREATE UNIQUE INDEX IF NOT EXISTS uq_counting_session_pc 
  ON counting_sessions (election_id, parliamentary_constituency_id) 
  WHERE parliamentary_constituency_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_counting_session_ac 
  ON counting_sessions (election_id, assembly_constituency_id) 
  WHERE assembly_constituency_id IS NOT NULL;

-- ============================================================================
-- SECTION 3: DECLARATIVE CHECK CONSTRAINTS
-- ============================================================================

-- 3.1 Constituency Type Mutual Exclusivity
ALTER TABLE election_constituencies
  ADD CONSTRAINT chk_election_constituency_type_exclusivity
  CHECK (
    (constituency_type = 'PARLIAMENTARY' AND parliamentary_constituency_id IS NOT NULL AND assembly_constituency_id IS NULL)
    OR
    (constituency_type = 'ASSEMBLY' AND assembly_constituency_id IS NOT NULL AND parliamentary_constituency_id IS NULL)
  );

ALTER TABLE candidate_nominations
  ADD CONSTRAINT chk_nomination_constituency_type_exclusivity
  CHECK (
    (constituency_type = 'PARLIAMENTARY' AND parliamentary_constituency_id IS NOT NULL AND assembly_constituency_id IS NULL)
    OR
    (constituency_type = 'ASSEMBLY' AND assembly_constituency_id IS NOT NULL AND parliamentary_constituency_id IS NULL)
  );

ALTER TABLE counting_sessions
  ADD CONSTRAINT chk_counting_session_constituency_type_exclusivity
  CHECK (
    (constituency_type = 'PARLIAMENTARY' AND parliamentary_constituency_id IS NOT NULL AND assembly_constituency_id IS NULL)
    OR
    (constituency_type = 'ASSEMBLY' AND assembly_constituency_id IS NOT NULL AND parliamentary_constituency_id IS NULL)
  );

-- 3.2 Election Scope CHECK Constraint
ALTER TABLE elections
  ADD CONSTRAINT chk_election_type_state_scope
  CHECK (
    (type = 'LOK_SABHA' AND state_id IS NULL)
    OR
    (type = 'STATE_ASSEMBLY' AND state_id IS NOT NULL)
  );

-- 3.3 Announcement Targeting CHECK Constraint
ALTER TABLE announcements
  ADD CONSTRAINT chk_announcement_constituency_targeting
  CHECK (
    (target_constituency_type IS NULL AND target_parliamentary_constituency_id IS NULL AND target_assembly_constituency_id IS NULL)
    OR
    (target_constituency_type = 'PARLIAMENTARY' AND target_parliamentary_constituency_id IS NOT NULL AND target_assembly_constituency_id IS NULL)
    OR
    (target_constituency_type = 'ASSEMBLY' AND target_assembly_constituency_id IS NOT NULL AND target_parliamentary_constituency_id IS NULL)
  );

-- 3.4 Numerical Bounds CHECK Constraints
ALTER TABLE counting_sessions
  ADD CONSTRAINT chk_counting_round_bounds
  CHECK (current_round <= total_configured_rounds AND total_configured_rounds >= 1 AND current_round >= 0);

ALTER TABLE counting_sessions
  ADD CONSTRAINT chk_counting_vote_non_negative
  CHECK (nota_votes >= 0 AND rejected_votes >= 0 AND total_counted_votes >= 0 AND total_voters >= 0 AND victory_margin >= 0);

ALTER TABLE counting_rounds
  ADD CONSTRAINT chk_counting_rounds_vote_non_negative
  CHECK (round_number >= 1 AND round_votes >= 0 AND cumulative_votes >= 0 AND lead_margin >= 0);

ALTER TABLE candidate_tallies
  ADD CONSTRAINT chk_tally_vote_and_share_bounds
  CHECK (votes >= 0 AND vote_share_percentage >= 0.00 AND vote_share_percentage <= 100.00);

-- ============================================================================
-- SECTION 4: ELECTION-TO-CONSTITUENCY COMPATIBILITY TRIGGERS
-- ============================================================================

-- 4.1 Verify Election-Constituency Compatibility
CREATE OR REPLACE FUNCTION verify_election_constituency_compatibility()
RETURNS TRIGGER AS $$
DECLARE
  v_election_type "ElectionType";
  v_election_state_id VARCHAR(10);
  v_ac_state_id VARCHAR(10);
BEGIN
  SELECT type, state_id INTO v_election_type, v_election_state_id 
  FROM elections WHERE id = NEW.election_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Referenced election % does not exist.', NEW.election_id;
  END IF;

  -- Rule A: LOK_SABHA election must map to PARLIAMENTARY constituency only
  IF v_election_type = 'LOK_SABHA' THEN
    IF NEW.constituency_type != 'PARLIAMENTARY' OR NEW.parliamentary_constituency_id IS NULL THEN
      RAISE EXCEPTION 'Lok Sabha election % cannot map to non-parliamentary constituency.', NEW.election_id;
    END IF;
  END IF;

  -- Rule B: STATE_ASSEMBLY election must map to ASSEMBLY constituency only
  IF v_election_type = 'STATE_ASSEMBLY' THEN
    IF NEW.constituency_type != 'ASSEMBLY' OR NEW.assembly_constituency_id IS NULL THEN
      RAISE EXCEPTION 'State Assembly election % cannot map to non-assembly constituency.', NEW.election_id;
    END IF;

    -- Rule C: Assembly constituency state must match election state
    SELECT state_id INTO v_ac_state_id 
    FROM assembly_constituencies WHERE id = NEW.assembly_constituency_id;

    IF v_ac_state_id != v_election_state_id THEN
      RAISE EXCEPTION 'Assembly constituency % state (%) does not match election % state (%).',
        NEW.assembly_constituency_id, v_ac_state_id, NEW.election_id, v_election_state_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_verify_election_constituency_compatibility ON election_constituencies;
CREATE TRIGGER trg_verify_election_constituency_compatibility
  BEFORE INSERT OR UPDATE ON election_constituencies
  FOR EACH ROW
  EXECUTE FUNCTION verify_election_constituency_compatibility();

-- 4.2 Verify Candidate Nomination Compatibility & Statutory Limit (RPA 1951 s.33(7))
CREATE OR REPLACE FUNCTION verify_candidate_nomination_compatibility()
RETURNS TRIGGER AS $$
DECLARE
  v_election_type "ElectionType";
  v_election_state_id VARCHAR(10);
  v_ac_state_id VARCHAR(10);
  v_nomination_count INT;
BEGIN
  SELECT type, state_id INTO v_election_type, v_election_state_id 
  FROM elections WHERE id = NEW.election_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Referenced election % does not exist.', NEW.election_id;
  END IF;

  IF v_election_type = 'LOK_SABHA' THEN
    IF NEW.constituency_type != 'PARLIAMENTARY' OR NEW.parliamentary_constituency_id IS NULL THEN
      RAISE EXCEPTION 'Lok Sabha nomination % must be in a Parliamentary Constituency.', NEW.id;
    END IF;
  END IF;

  IF v_election_type = 'STATE_ASSEMBLY' THEN
    IF NEW.constituency_type != 'ASSEMBLY' OR NEW.assembly_constituency_id IS NULL THEN
      RAISE EXCEPTION 'State Assembly nomination % must be in an Assembly Constituency.', NEW.id;
    END IF;

    SELECT state_id INTO v_ac_state_id 
    FROM assembly_constituencies WHERE id = NEW.assembly_constituency_id;

    IF v_ac_state_id != v_election_state_id THEN
      RAISE EXCEPTION 'Nomination constituency state (%) does not match election state (%).',
        v_ac_state_id, v_election_state_id;
    END IF;
  END IF;

  -- Statutory Limit: Section 33(7) RPA 1951 allows up to 2 active nominations per election
  SELECT COUNT(*) INTO v_nomination_count
  FROM candidate_nominations
  WHERE candidate_id = NEW.candidate_id 
    AND election_id = NEW.election_id
    AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
    AND status NOT IN ('REJECTED', 'WITHDRAWN');

  IF v_nomination_count >= 2 THEN
    RAISE EXCEPTION 'Candidate % exceeds statutory limit of 2 nominations in election % (RPA 1951 s.33(7)).',
      NEW.candidate_id, NEW.election_id;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_verify_candidate_nomination_compatibility ON candidate_nominations;
CREATE TRIGGER trg_verify_candidate_nomination_compatibility
  BEFORE INSERT OR UPDATE ON candidate_nominations
  FOR EACH ROW
  EXECUTE FUNCTION verify_candidate_nomination_compatibility();

-- 4.3 Verify Counting Session Compatibility
CREATE OR REPLACE FUNCTION verify_counting_session_compatibility()
RETURNS TRIGGER AS $$
DECLARE
  v_election_type "ElectionType";
  v_election_state_id VARCHAR(10);
  v_ac_state_id VARCHAR(10);
BEGIN
  SELECT type, state_id INTO v_election_type, v_election_state_id 
  FROM elections WHERE id = NEW.election_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Referenced election % does not exist.', NEW.election_id;
  END IF;

  IF v_election_type = 'LOK_SABHA' THEN
    IF NEW.constituency_type != 'PARLIAMENTARY' OR NEW.parliamentary_constituency_id IS NULL THEN
      RAISE EXCEPTION 'Counting session % for Lok Sabha must reference a Parliamentary Constituency.', NEW.id;
    END IF;
  END IF;

  IF v_election_type = 'STATE_ASSEMBLY' THEN
    IF NEW.constituency_type != 'ASSEMBLY' OR NEW.assembly_constituency_id IS NULL THEN
      RAISE EXCEPTION 'Counting session % for State Assembly must reference an Assembly Constituency.', NEW.id;
    END IF;

    SELECT state_id INTO v_ac_state_id 
    FROM assembly_constituencies WHERE id = NEW.assembly_constituency_id;

    IF v_ac_state_id != v_election_state_id THEN
      RAISE EXCEPTION 'Counting session constituency state (%) does not match election state (%).',
        v_ac_state_id, v_election_state_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_verify_counting_session_compatibility ON counting_sessions;
CREATE TRIGGER trg_verify_counting_session_compatibility
  BEFORE INSERT OR UPDATE ON counting_sessions
  FOR EACH ROW
  EXECUTE FUNCTION verify_counting_session_compatibility();

-- ============================================================================
-- SECTION 5: CANDIDATE NOMINATION & TALLY INTEGRITY TRIGGERS
-- ============================================================================

-- 5.1 Enforce Approved Nomination for Every Candidate Tally
CREATE OR REPLACE FUNCTION verify_candidate_tally_nomination()
RETURNS TRIGGER AS $$
DECLARE
  v_election_id VARCHAR(50);
  v_constituency_type "ConstituencyType";
  v_pc_id VARCHAR(50);
  v_ac_id VARCHAR(50);
  v_candidate_party_id VARCHAR(50);
  v_nomination_id UUID;
BEGIN
  -- Rejection of NOTA as an ordinary candidate (NOTA must use nota_votes column)
  IF UPPER(NEW.candidate_id) = 'NOTA' OR UPPER(NEW.candidate_id) LIKE '%NOTA%' THEN
    RAISE EXCEPTION 'NOTA must not be tallied as a candidate. Use counting_sessions.nota_votes.';
  END IF;

  -- 1. Get counting session context
  SELECT election_id, constituency_type, parliamentary_constituency_id, assembly_constituency_id
  INTO v_election_id, v_constituency_type, v_pc_id, v_ac_id
  FROM counting_sessions WHERE id = NEW.session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Parent counting session % not found.', NEW.session_id;
  END IF;

  -- 2. Verify candidate's registered party matches tally
  SELECT party_id INTO v_candidate_party_id 
  FROM candidates WHERE id = NEW.candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Candidate % not found.', NEW.candidate_id;
  END IF;

  IF v_candidate_party_id != NEW.party_id THEN
    RAISE EXCEPTION 'Tally party (%) does not match registered party (%) for candidate %.',
      NEW.party_id, v_candidate_party_id, NEW.candidate_id;
  END IF;

  -- 3. Verify candidate has an APPROVED nomination in that election and exact constituency
  IF v_constituency_type = 'PARLIAMENTARY' THEN
    SELECT id INTO v_nomination_id
    FROM candidate_nominations
    WHERE candidate_id = NEW.candidate_id
      AND election_id = v_election_id
      AND constituency_type = 'PARLIAMENTARY'
      AND parliamentary_constituency_id = v_pc_id
      AND status = 'APPROVED';
  ELSE
    SELECT id INTO v_nomination_id
    FROM candidate_nominations
    WHERE candidate_id = NEW.candidate_id
      AND election_id = v_election_id
      AND constituency_type = 'ASSEMBLY'
      AND assembly_constituency_id = v_ac_id
      AND status = 'APPROVED';
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Candidate % does not hold an APPROVED nomination for election % in constituency %.',
      NEW.candidate_id, v_election_id, COALESCE(v_pc_id, v_ac_id);
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_verify_candidate_tally_nomination ON candidate_tallies;
CREATE TRIGGER trg_verify_candidate_tally_nomination
  BEFORE INSERT OR UPDATE ON candidate_tallies
  FOR EACH ROW
  EXECUTE FUNCTION verify_candidate_tally_nomination();

-- 5.2 Verify Winner, Runner-Up, and Round Leader Nominations in Counting Sessions
CREATE OR REPLACE FUNCTION verify_counting_session_candidates()
RETURNS TRIGGER AS $$
DECLARE
  v_nom_id UUID;
BEGIN
  -- Prevent winner and runner-up from being the same candidate
  IF NEW.winner_candidate_id IS NOT NULL AND NEW.runner_up_candidate_id IS NOT NULL THEN
    IF NEW.winner_candidate_id = NEW.runner_up_candidate_id THEN
      RAISE EXCEPTION 'Winner candidate (%) and runner-up candidate cannot be identical.', NEW.winner_candidate_id;
    END IF;
  END IF;

  -- Winner must have APPROVED nomination
  IF NEW.winner_candidate_id IS NOT NULL THEN
    IF NEW.constituency_type = 'PARLIAMENTARY' THEN
      SELECT id INTO v_nom_id FROM candidate_nominations
      WHERE candidate_id = NEW.winner_candidate_id AND election_id = NEW.election_id
        AND parliamentary_constituency_id = NEW.parliamentary_constituency_id AND status = 'APPROVED';
    ELSE
      SELECT id INTO v_nom_id FROM candidate_nominations
      WHERE candidate_id = NEW.winner_candidate_id AND election_id = NEW.election_id
        AND assembly_constituency_id = NEW.assembly_constituency_id AND status = 'APPROVED';
    END IF;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Declared winner % lacks an APPROVED nomination in session constituency.', NEW.winner_candidate_id;
    END IF;
  END IF;

  -- Runner-up must have APPROVED nomination
  IF NEW.runner_up_candidate_id IS NOT NULL THEN
    IF NEW.constituency_type = 'PARLIAMENTARY' THEN
      SELECT id INTO v_nom_id FROM candidate_nominations
      WHERE candidate_id = NEW.runner_up_candidate_id AND election_id = NEW.election_id
        AND parliamentary_constituency_id = NEW.parliamentary_constituency_id AND status = 'APPROVED';
    ELSE
      SELECT id INTO v_nom_id FROM candidate_nominations
      WHERE candidate_id = NEW.runner_up_candidate_id AND election_id = NEW.election_id
        AND assembly_constituency_id = NEW.assembly_constituency_id AND status = 'APPROVED';
    END IF;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Declared runner-up % lacks an APPROVED nomination in session constituency.', NEW.runner_up_candidate_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_verify_counting_session_candidates ON counting_sessions;
CREATE TRIGGER trg_verify_counting_session_candidates
  BEFORE INSERT OR UPDATE ON counting_sessions
  FOR EACH ROW
  EXECUTE FUNCTION verify_counting_session_candidates();

-- ============================================================================
-- SECTION 6: RESULT PUBLICATION STATE MACHINE HARDENING
-- ============================================================================

CREATE OR REPLACE FUNCTION verify_counting_session_publication()
RETURNS TRIGGER AS $$
DECLARE
  v_correction_count INT;
BEGIN
  -- ==========================================================================
  -- 6.1 INSERT Path Protection: Sessions MUST be created in DRAFT
  -- ==========================================================================
  IF TG_OP = 'INSERT' THEN
    IF NEW.is_published = TRUE OR NEW.status = 'PUBLISHED' THEN
      RAISE EXCEPTION 'New counting sessions cannot be directly inserted as PUBLISHED. Must begin in DRAFT.';
    END IF;
    IF NEW.status NOT IN ('DRAFT', 'COUNTING_IN_PROGRESS') THEN
      RAISE EXCEPTION 'Invalid initial state % for counting session. Must be DRAFT.', NEW.status;
    END IF;
    RETURN NEW;
  END IF;

  -- ==========================================================================
  -- 6.2 UPDATE Path: State Transition Graph Validation
  -- ==========================================================================
  IF TG_OP = 'UPDATE' AND OLD.status != NEW.status THEN
    CASE OLD.status
      WHEN 'DRAFT' THEN
        IF NEW.status NOT IN ('COUNTING_IN_PROGRESS', 'UNPUBLISHED') THEN
          RAISE EXCEPTION 'Illegal state transition from DRAFT to %.', NEW.status;
        END IF;

      WHEN 'COUNTING_IN_PROGRESS' THEN
        IF NEW.status NOT IN ('COUNTING_PAUSED', 'COUNTING_COMPLETED', 'TIED', 'UNPUBLISHED') THEN
          RAISE EXCEPTION 'Illegal state transition from COUNTING_IN_PROGRESS to %.', NEW.status;
        END IF;

      WHEN 'COUNTING_PAUSED' THEN
        IF NEW.status NOT IN ('COUNTING_IN_PROGRESS', 'UNPUBLISHED') THEN
          RAISE EXCEPTION 'Illegal state transition from COUNTING_PAUSED to %.', NEW.status;
        END IF;

      WHEN 'COUNTING_COMPLETED' THEN
        IF NEW.status NOT IN ('RESULT_READY_FOR_REVIEW', 'TIED', 'UNDER_REVIEW') THEN
          RAISE EXCEPTION 'Illegal state transition from COUNTING_COMPLETED to %. Must proceed to RESULT_READY_FOR_REVIEW.', NEW.status;
        END IF;

      WHEN 'TIED' THEN
        IF NEW.status NOT IN ('UNDER_REVIEW', 'RESULT_READY_FOR_REVIEW') THEN
          RAISE EXCEPTION 'Tied result cannot transition to % without formal tie-break review.', NEW.status;
        END IF;

      WHEN 'RESULT_READY_FOR_REVIEW' THEN
        IF NEW.status NOT IN ('PUBLISHED', 'UNDER_REVIEW', 'COUNTING_IN_PROGRESS') THEN
          RAISE EXCEPTION 'Illegal state transition from RESULT_READY_FOR_REVIEW to %.', NEW.status;
        END IF;

      WHEN 'PUBLISHED' THEN
        IF NEW.status NOT IN ('UNDER_REVIEW', 'UNPUBLISHED') THEN
          RAISE EXCEPTION 'Published result cannot transition directly to %. Must be placed UNDER_REVIEW or UNPUBLISHED.', NEW.status;
        END IF;

      WHEN 'UNDER_REVIEW' THEN
        IF NEW.status NOT IN ('CORRECTED', 'RESULT_READY_FOR_REVIEW', 'UNPUBLISHED') THEN
          RAISE EXCEPTION 'Illegal state transition from UNDER_REVIEW to %.', NEW.status;
        END IF;

      WHEN 'CORRECTED' THEN
        IF NEW.status NOT IN ('RESULT_READY_FOR_REVIEW', 'UNDER_REVIEW') THEN
          RAISE EXCEPTION 'Corrected result must return to RESULT_READY_FOR_REVIEW before publication.', NEW.status;
        END IF;

      WHEN 'UNPUBLISHED' THEN
        IF NEW.status NOT IN ('UNDER_REVIEW', 'DRAFT') THEN
          RAISE EXCEPTION 'Illegal state transition from UNPUBLISHED to %.', NEW.status;
        END IF;

      ELSE
        RAISE EXCEPTION 'Unknown previous status %.', OLD.status;
    END CASE;
  END IF;

  -- ==========================================================================
  -- 6.3 Publication Invariant Enforcement (is_published = TRUE)
  -- ==========================================================================
  IF NEW.is_published = TRUE AND (OLD.is_published = FALSE OR OLD.status != 'PUBLISHED') THEN
    -- Rule 1: Cannot publish directly from DRAFT or COUNTING_COMPLETED.
    -- Publication REQUIRES an approved review stage (previous status must be RESULT_READY_FOR_REVIEW).
    IF OLD.status != 'RESULT_READY_FOR_REVIEW' THEN
      RAISE EXCEPTION 'Cannot publish result from status %; must be reviewed in RESULT_READY_FOR_REVIEW stage first.', OLD.status;
    END IF;

    -- Rule 2: Result status must be set to PUBLISHED
    IF NEW.status != 'PUBLISHED' THEN
      RAISE EXCEPTION 'Result flagged as is_published must have status = PUBLISHED (current: %).', NEW.status;
    END IF;

    -- Rule 3: Incomplete counting session cannot be published
    IF NEW.current_round < NEW.total_configured_rounds THEN
      RAISE EXCEPTION 'Cannot publish result: counting is incomplete (% of % rounds completed).',
        NEW.current_round, NEW.total_configured_rounds;
    END IF;

    -- Rule 4: Tied results cannot be published without resolution
    IF NEW.status = 'TIED' OR OLD.status = 'TIED' THEN
      RAISE EXCEPTION 'Cannot publish result while in TIED status.';
    END IF;

    -- Rule 5: Publication must record publishing administrator and timestamp
    IF NEW.published_by_admin_id IS NULL THEN
      RAISE EXCEPTION 'Publication rejected: published_by_admin_id must be populated.';
    END IF;

    IF NEW.published_at IS NULL THEN
      NEW.published_at := NOW();
    END IF;

    -- Rule 6: Winner must be declared
    IF NEW.winner_candidate_id IS NULL AND NEW.total_counted_votes > 0 THEN
      RAISE EXCEPTION 'Cannot publish result without a declared winner.';
    END IF;
  END IF;

  -- ==========================================================================
  -- 6.4 Correction Audit Trail Invariant
  -- ==========================================================================
  IF OLD.status = 'UNDER_REVIEW' AND NEW.status = 'CORRECTED' THEN
    SELECT COUNT(*) INTO v_correction_count
    FROM result_correction_history
    WHERE session_id = NEW.id;

    IF v_correction_count = 0 THEN
      RAISE EXCEPTION 'Cannot transition to CORRECTED without an immutable result_correction_history entry.';
    END IF;
  END IF;

  -- Synchronization: If status is not PUBLISHED, is_published must be false
  IF NEW.status != 'PUBLISHED' AND NEW.is_published = TRUE THEN
    NEW.is_published := FALSE;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_verify_counting_session_publication ON counting_sessions;
CREATE TRIGGER trg_verify_counting_session_publication
  BEFORE INSERT OR UPDATE ON counting_sessions
  FOR EACH ROW
  EXECUTE FUNCTION verify_counting_session_publication();

-- ============================================================================
-- SECTION 7: COUNTING RECONCILIATION & NUMERICAL INTEGRITY
-- ============================================================================

-- 7.1 Reconcile Counting Session Vote Sums
-- Formula: total_counted_votes = SUM(candidate_tallies.votes) + nota_votes + rejected_votes
CREATE OR REPLACE FUNCTION reconcile_counting_session_votes()
RETURNS TRIGGER AS $$
DECLARE
  v_candidate_votes_sum INT;
  v_calculated_total INT;
BEGIN
  -- Only perform strict reconciliation once counting has commenced
  IF NEW.current_round > 0 OR NEW.status IN ('COUNTING_COMPLETED', 'RESULT_READY_FOR_REVIEW', 'PUBLISHED') THEN
    SELECT COALESCE(SUM(votes), 0) INTO v_candidate_votes_sum
    FROM candidate_tallies
    WHERE session_id = NEW.id;

    v_calculated_total := v_candidate_votes_sum + NEW.nota_votes + NEW.rejected_votes;

    -- If tally records exist and total is populated, enforce equality
    IF v_candidate_votes_sum > 0 AND NEW.total_counted_votes != v_calculated_total THEN
      RAISE EXCEPTION 'Vote reconciliation error in session %: total_counted_votes (%) != sum of candidate votes (%) + NOTA (%) + rejected (%).',
        NEW.id, NEW.total_counted_votes, v_candidate_votes_sum, NEW.nota_votes, NEW.rejected_votes;
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_reconcile_counting_session_votes ON counting_sessions;
CREATE TRIGGER trg_reconcile_counting_session_votes
  BEFORE UPDATE ON counting_sessions
  FOR EACH ROW
  EXECUTE FUNCTION reconcile_counting_session_votes();

-- 7.2 Verify Sequential Counting Rounds Progression
-- Invariants:
-- 1. Round numbers must be sequential (1, 2, ... N).
-- 2. Cumulative votes cannot decrease between rounds.
-- 3. Round votes cannot exceed cumulative votes.
CREATE OR REPLACE FUNCTION verify_counting_round_progression()
RETURNS TRIGGER AS $$
DECLARE
  v_prev_cumulative INT;
  v_configured_rounds INT;
BEGIN
  SELECT total_configured_rounds INTO v_configured_rounds
  FROM counting_sessions WHERE id = NEW.session_id;

  IF NEW.round_number > v_configured_rounds THEN
    RAISE EXCEPTION 'Round number % exceeds session configured rounds %.', 
      NEW.round_number, v_configured_rounds;
  END IF;

  IF NEW.round_number > 1 THEN
    SELECT cumulative_votes INTO v_prev_cumulative
    FROM counting_rounds
    WHERE session_id = NEW.session_id AND round_number = NEW.round_number - 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Cannot insert round % before round % is recorded.',
        NEW.round_number, NEW.round_number - 1;
    END IF;

    IF NEW.cumulative_votes < v_prev_cumulative THEN
      RAISE EXCEPTION 'Cumulative votes decreasing in round % (current: %, previous: %).',
        NEW.round_number, NEW.cumulative_votes, v_prev_cumulative;
    END IF;

    IF NEW.round_votes != (NEW.cumulative_votes - v_prev_cumulative) THEN
      RAISE EXCEPTION 'Round % votes (%) does not match delta between cumulative totals (%).',
        NEW.round_number, NEW.round_votes, (NEW.cumulative_votes - v_prev_cumulative);
    END IF;
  ELSE
    IF NEW.round_votes != NEW.cumulative_votes THEN
      RAISE EXCEPTION 'In round 1, round_votes (%) must equal cumulative_votes (%).',
        NEW.round_votes, NEW.cumulative_votes;
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_verify_counting_round_progression ON counting_rounds;
CREATE TRIGGER trg_verify_counting_round_progression
  BEFORE INSERT OR UPDATE ON counting_rounds
  FOR EACH ROW
  EXECUTE FUNCTION verify_counting_round_progression();
